function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a1f14', W='#8b5a2b', WL='#c48a4a', WD='#5a3a18', M='#9aa3ad';
  px(5,9,22,20,O);
  px(6,10,20,18,W);
  px(6,10,20,2,WL); px(6,26,20,2,WD);
  px(6,10,1,18,WL); px(25,10,1,18,WD);
  for (let i=0;i<14;i++) {
    px(7+i,11+Math.floor(i*12/13),1,2,WD);
    px(24-i,11+Math.floor(i*12/13),1,2,WD);
  }
  px(6,18,20,1,O);
  px(14,20,4,5,M); px(15,22,2,2,O);
}
